@if($report['vendedores']->isEmpty())<p class="empty">No hay vendedores en este equipo.</p>@else<table class="table table-mobile"><thead><tr><th>Vendedor</th><th>Cartera</th><th>Ventas</th><th>Total vendido</th><th>Pronóstico</th></tr></thead><tbody>@foreach($report['vendedores'] as $v)<tr><td data-label="Vendedor"><strong>{{ $v['nombre'] }}</strong><small>{{ $v['activo']?'Cuenta activa':'Cuenta desactivada' }}</small></td><td data-label="Cartera">{{ $v['cartera'] }} / 10</td><td data-label="Ventas">{{ $v['ventas'] }}</td><td data-label="Total vendido">Q{{ number_format($v['total'],2) }}</td><td data-label="Pronóstico">Q{{ number_format($v['pronostico'],2) }}</td></tr>@endforeach</tbody></table>@endif
